import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import SnackBar from "@/components/SnackBar.vue";
import { useDisplay } from "vuetify/lib/framework.mjs";
import CreateLocationQR from "@/components/SettingsDialogs/CreateLocationQR.vue";
import { list_all_locations } from "@/graphql/queries.js";
import LocationQrList from "@/components/SettingsDialogs/LocationQrList.vue";
import LocationQRview from "@/components/SettingsDialogs/LocationQRview.vue";
import { API, graphqlOperation } from "aws-amplify";
import DoorlockDialog from "./DoorlockDialog.vue";
export default {
  components: {
    SnackBar,
    CreateLocationQR,
    LocationQRview,
    LocationQrList,
    DoorlockDialog
  },
  data() {
    return {
      headers: [{
        title: "Location",
        value: "location_name",
        sortable: true,
        align: "start"
      }, {
        title: "QR",
        value: "qr_details",
        sortable: false,
        align: "center"
      }, {
        title: "Address",
        value: "location_address",
        sortable: true,
        align: "start"
      },
      // { title: "Doorlock", value: "door_enabled", sortable: false, align: "center" },
      {
        title: "Action",
        value: "actions",
        sortable: false,
        align: "center"
      }],
      tableData: [],
      tableLoading: false,
      qrCreation: false,
      qrListLocation: false,
      qrLocation: false,
      next_token: null,
      componentCheck: 0,
      rowInfo: {},
      SnackBarComponent: {},
      CommonVuetifyObj: {},
      search: "",
      searchQuery: "",
      sortBy: [{
        key: "location_name",
        order: "asc"
      }],
      fixed: true,
      height: 0,
      qrtype: "Single",
      page: 1,
      itemsPerPage: 100,
      currentPage: 1,
      totalCount: 0,
      doorDialog: false,
      doorDialogItem: null
    };
  },
  created() {
    this.height = window.innerHeight - 260;
  },
  watch: {},
  mounted() {
    this.CommonVuetifyObj = useDisplay();
    this.fetch_master_locations();
  },
  methods: {
    add_locationQR(item) {
      this.componentCheck = 1;
      this.rowInfo = item;
      this.qrCreation = true;
    },
    qrmultipleView(item) {
      this.componentCheck = 3;
      this.rowInfo = item;
      this.qrListLocation = true;
    },
    qrView(item) {
      this.componentCheck = 2;
      this.rowInfo = item;
      this.qrLocation = true;
    },
    async fetch_master_locations() {
      this.tableLoading = true;
      let data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_all_locations, {
          organization_id: data.organization.organization_id,
          location_status: "ACTIVE",
          limit: 500,
          next_token: null
        }));
        this.tableLoading = false;
        this.tableData = [];
        let response = result.data.list_all_locations;
        this.tableData = response.details;
        this.tableData = this.tableData.filter(obj => obj.location_type != "SCAN_ANYWHERE");
        this.totalCount = this.tableData.length;
        this.currentPage = 1;
        // console.log(result, "result");
      } catch (error) {
        this.tableLoading = false;
        this.tableData = [];
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.qrCreation = false;
      this.fetch_master_locations();
    },
    handleSortChange(newSortBy) {
      this.sortBy = newSortBy;
      this.updatePageItems();
    },
    getSortValue(value, key) {
      if (!value) return "";
      if (key === "location_name" || key === "location_address") {
        return value.toLowerCase();
      }
      return value;
    },
    updatePageItems() {},
    openDoorDialog(item) {
      this.doorDialogItem = item;
      this.doorDialog = true;
    },
    handleToggleDoor(item) {
      if (item) {
        item.door_enabled = !item.door_enabled;
        this.doorDialog = false;
      }
    }
  },
  computed: {
    totalCount() {
      return this.tableData.length;
    },
    startItem() {
      return (this.currentPage - 1) * this.itemsPerPage + 1;
    },
    endItem() {
      return Math.min(this.currentPage * this.itemsPerPage, this.totalCount);
    },
    pageCount() {
      return Math.ceil(this.tableData.length / this.itemsPerPage);
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.tableData.slice(start, end);
    },
    sortedAndPaginatedItems() {
      const sortedItems = this.paginatedItems.slice().sort((a, b) => {
        for (const sort of this.sortBy) {
          const aValue = this.getSortValue(a[sort.key], sort.key);
          const bValue = this.getSortValue(b[sort.key], sort.key);
          if (aValue < bValue) return sort.order === "asc" ? -1 : 1;
          if (aValue > bValue) return sort.order === "asc" ? 1 : -1;
        }
        return 0;
      });
      return sortedItems;
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.min(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  }
};
